/**
 * Looks + motion layer
 * Design types (look) + micro-interactions for all controls.
 * Respects prefers-reduced-motion.
 */

:root {
  --sg-ease-spring: cubic-bezier(0.34, 1.4, 0.64, 1);
  --sg-ease-smooth: cubic-bezier(0.22, 1, 0.36, 1);
  --sg-motion-fast: 160ms;
  --sg-motion-med: 240ms;
}

/* —— Shared transition surfaces (recipes live in motion-recipes.css) —— */
.sg-btn,
.sg-select-trigger,
.sg-select-option,
.sg-tabs-trigger,
.sg-check-control,
.sg-switch,
.sg-badge,
.sg-shell-nav-item {
  transition:
    transform var(--sg-motion-fast) var(--sg-ease-spring),
    background var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth),
    color var(--sg-motion-fast) var(--sg-ease-smooth),
    opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    filter var(--sg-motion-fast) var(--sg-ease-smooth);
}

/* Nav + select chrome keep a light lift (not part of atom motion menus) */
.sg-select-trigger:hover:not(:disabled),
.sg-shell-nav-item:hover {
  transform: translateY(-1px);
}

.sg-select-trigger:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

.sg-check-control {
  transition:
    transform var(--sg-motion-fast) var(--sg-ease-spring),
    background var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-check-root:hover .sg-check-control:not([data-checked="true"]) {
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-frost));
}

.sg-check-root:not([data-motion="none"]):hover
  .sg-check-control:not([data-checked="true"]) {
  transform: scale(1.06);
}

.sg-card {
  transition:
    transform var(--sg-motion-med) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth);
}

/* Default tooltip closed/open poses — refined by data-motion recipes */
.sg-tooltip {
  transition:
    opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    visibility var(--sg-motion-fast) var(--sg-ease-smooth),
    transform var(--sg-motion-med) var(--sg-ease-spring);
  transform: translateX(-50%) translateY(4px) scale(0.96);
}

.sg-tooltip[data-open="true"] {
  transform: translateX(-50%) translateY(0) scale(1);
}

.sg-tooltip[data-placement="bottom"] {
  transform: translateX(-50%) translateY(-4px) scale(0.96);
}

.sg-tooltip[data-placement="bottom"][data-open="true"] {
  transform: translateX(-50%) translateY(0) scale(1);
}

.sg-select-menu {
  transform-origin: top center;
}

.sg-select-option {
  transition:
    transform var(--sg-motion-fast) var(--sg-ease-spring),
    background var(--sg-motion-fast) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    color var(--sg-motion-fast) var(--sg-ease-smooth);
}

.sg-select-option:hover:not(:disabled):not([data-selected="true"]),
.sg-select-option[data-highlighted="true"]:not([data-selected="true"]) {
  transform: translateX(2px);
}

.sg-avatar {
  transition:
    transform var(--sg-motion-fast) var(--sg-ease-spring),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-switch-thumb {
  transition: transform var(--sg-motion-med) var(--sg-ease-spring),
    background var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-fast) var(--sg-ease-smooth);
}

@keyframes sg-pop {
  0% {
    transform: scale(0.86);
  }
  60% {
    transform: scale(1.08);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes sg-sheen {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes sg-pulse-soft {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--sg-accent) 35%, transparent);
  }
  50% {
    box-shadow: 0 0 0 6px color-mix(in srgb, var(--sg-accent) 0%, transparent);
  }
}

/* ========== BUTTON LOOKS ========== */
/* look works with variant — solid is default (no extra class) */

.sg-btn-look-soft.sg-btn-primary {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-accent) 22%, transparent);
  box-shadow: none;
}

.sg-btn-look-soft.sg-btn-primary:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-btn-look-soft.sg-btn-danger {
  background: color-mix(in srgb, var(--sg-danger) 14%, transparent);
  color: var(--sg-danger);
  box-shadow: none;
}

.sg-btn-look-glass {
  background: var(--sg-surface-frost) !important;
  color: var(--sg-fg) !important;
  border-color: var(--sg-border-frost) !important;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight), var(--sg-shadow-soft) !important;
}

.sg-btn-look-glass:hover:not(:disabled) {
  background: var(--sg-surface-frost-strong) !important;
  transform: translateY(-2px);
}

.sg-btn-look-gradient.sg-btn-primary,
.sg-btn-look-gradient.sg-btn-danger {
  background-image: linear-gradient(
    125deg,
    var(--sg-accent) 0%,
    color-mix(in srgb, var(--sg-accent) 55%, #fff) 45%,
    var(--sg-accent-hover) 100%
  ) !important;
  background-size: 160% 160%;
  border-color: transparent !important;
  color: var(--sg-accent-fg) !important;
  box-shadow: var(--sg-shadow-soft), inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-btn-look-gradient.sg-btn-danger {
  background-image: linear-gradient(
    125deg,
    var(--sg-danger),
    color-mix(in srgb, var(--sg-danger) 60%, #fbbf24)
  ) !important;
}

.sg-btn-look-gradient:hover:not(:disabled) {
  background-position: 100% 50%;
  filter: brightness(1.05);
}

.sg-btn-look-neon {
  background: transparent !important;
  color: var(--sg-accent) !important;
  border-color: var(--sg-accent) !important;
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--sg-accent) 30%, transparent),
    0 0 18px color-mix(in srgb, var(--sg-accent) 28%, transparent),
    inset 0 0 12px color-mix(in srgb, var(--sg-accent) 12%, transparent) !important;
}

.sg-btn-look-neon:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-accent) 12%, transparent) !important;
  box-shadow:
    0 0 0 1px var(--sg-accent),
    0 0 28px color-mix(in srgb, var(--sg-accent) 45%, transparent) !important;
  animation: sg-pulse-soft 1.6s ease-in-out infinite;
}

.sg-btn-look-neon.sg-btn-danger {
  color: var(--sg-danger) !important;
  border-color: var(--sg-danger) !important;
}

/* ========== RADIO LOOKS ========== */
/* 1) dot — default (already) */

/* 2) card — selectable panel */
.sg-check-root[data-look="card"] {
  display: flex;
  width: 100%;
  padding: 0.85rem 1rem;
  border-radius: var(--sg-radius-md);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  gap: 0.85rem;
  align-items: center;
}

.sg-check-root[data-look="card"]:hover {
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-frost));
  transform: translateY(-1px);
  box-shadow: var(--sg-shadow-soft);
}

.sg-check-root[data-look="card"]:has(input:checked),
.sg-check-root[data-look="card"][data-checked="true"] {
  border-color: var(--sg-accent);
  background: var(--sg-accent-soft);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--sg-accent) 35%, transparent),
    var(--sg-shadow-soft);
}

.sg-check-root[data-look="card"] .sg-check-control {
  margin-top: 0;
}

.sg-check-group[data-look="card"] {
  gap: 0.65rem;
}

/* 3) chip — horizontal pills */
.sg-check-group[data-look="chip"] {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.sg-check-root[data-look="chip"] {
  padding: 0.45rem 0.85rem 0.45rem 0.55rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  align-items: center;
  gap: 0.45rem;
}

.sg-check-root[data-look="chip"] .sg-check-control {
  width: 1rem;
  height: 1rem;
  margin-top: 0;
}

.sg-check-root[data-look="chip"]:has(input:checked),
.sg-check-root[data-look="chip"][data-checked="true"] {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  animation: sg-pop var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-check-root[data-look="chip"]:has(input:checked) .sg-check-label,
.sg-check-root[data-look="chip"][data-checked="true"] .sg-check-label {
  color: var(--sg-accent-fg);
}

.sg-check-root[data-look="chip"]:has(input:checked) .sg-check-hint,
.sg-check-root[data-look="chip"][data-checked="true"] .sg-check-hint {
  color: color-mix(in srgb, var(--sg-accent-fg) 80%, transparent);
}

.sg-check-root[data-look="chip"]:has(input:checked) .sg-check-control,
.sg-check-root[data-look="chip"][data-checked="true"] .sg-check-control {
  background: color-mix(in srgb, #fff 22%, transparent);
  border-color: transparent;
}

/* ========== CHECKBOX LOOKS ========== */
.sg-check-root[data-look="pill"] {
  padding: 0.4rem 0.85rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  align-items: center;
}

.sg-check-root[data-look="pill"]:has(input:checked) {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 40%, transparent);
}

.sg-check-root[data-look="pill"] .sg-check-control {
  border-radius: var(--sg-radius-pill);
  margin-top: 0;
}

/* ========== SWITCH LOOKS ========== */
.sg-switch[data-look="ios"] {
  width: 3rem;
  height: 1.75rem;
  background: color-mix(in srgb, var(--sg-fg-muted) 28%, transparent);
  border: none;
}

.sg-switch[data-look="ios"] .sg-switch-thumb {
  width: 1.4rem;
  height: 1.4rem;
  left: 0.18rem;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18);
}

.sg-switch[data-look="ios"][data-checked="true"] {
  background: var(--sg-success);
}

.sg-switch[data-look="ios"][data-checked="true"] .sg-switch-thumb {
  transform: translate(1.2rem, -50%);
}

.sg-switch[data-look="minimal"] {
  width: 2.4rem;
  height: 0.55rem;
  background: var(--sg-border-subtle);
  border: none;
  box-shadow: none;
}

.sg-switch[data-look="minimal"] .sg-switch-thumb {
  width: 1rem;
  height: 1rem;
  left: 0;
  background: var(--sg-surface-frost-strong);
  border: 2px solid var(--sg-border-frost);
}

.sg-switch[data-look="minimal"][data-checked="true"] {
  background: color-mix(in srgb, var(--sg-accent) 45%, transparent);
}

.sg-switch[data-look="minimal"][data-checked="true"] .sg-switch-thumb {
  background: var(--sg-accent);
  border-color: transparent;
  transform: translate(1.35rem, -50%);
}

/* ========== BADGE LOOKS ========== */
.sg-badge-look-outline {
  background: transparent;
  border-color: currentColor;
  opacity: 0.95;
}

.sg-badge-look-glow {
  box-shadow: 0 0 14px color-mix(in srgb, var(--sg-accent) 35%, transparent);
  animation: sg-pulse-soft 2.4s ease-in-out infinite;
}

.sg-badge-look-solid.sg-badge:not(.sg-badge-accent):not(.sg-badge-success):not(
    .sg-badge-warning
  ):not(.sg-badge-danger) {
  background: var(--sg-fg);
  color: var(--sg-bg);
  border-color: transparent;
}

/* ========== FIELD LOOKS (input / textarea) ========== */
.sg-input[data-look="underline"],
.sg-textarea[data-look="underline"] {
  border-radius: 0;
  border-width: 0 0 2px;
  border-color: var(--sg-border-subtle);
  background: transparent;
  box-shadow: none;
  padding-left: 0.15rem;
  padding-right: 0.15rem;
}

.sg-input[data-look="underline"]:focus,
.sg-textarea[data-look="underline"]:focus {
  border-color: var(--sg-accent);
  box-shadow: none;
}

.sg-input[data-look="filled"],
.sg-textarea[data-look="filled"] {
  background: var(--sg-accent-soft);
  border-color: transparent;
}

.sg-input[data-look="filled"]:focus,
.sg-textarea[data-look="filled"]:focus {
  background: var(--sg-surface-solid);
  border-color: var(--sg-accent);
}

.sg-input[data-look="ghost"],
.sg-textarea[data-look="ghost"] {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

.sg-input[data-look="ghost"]:hover,
.sg-textarea[data-look="ghost"]:hover {
  background: var(--sg-accent-soft);
}

.sg-input[data-look="ghost"]:focus,
.sg-textarea[data-look="ghost"]:focus {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

/* ========== SELECT LOOKS ========== */
.sg-select-trigger[data-look="soft"] {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 20%, transparent);
}

.sg-select-trigger[data-look="glass"] {
  background: var(--sg-surface-frost);
  border-color: var(--sg-border-frost);
}

.sg-select-trigger[data-look="gradient"] {
  background-image: linear-gradient(
    120deg,
    var(--sg-accent-soft),
    var(--sg-surface-frost-strong)
  );
  border-color: color-mix(in srgb, var(--sg-accent) 25%, transparent);
}

/* ========== TABS LOOKS ========== */
.sg-tabs-list[data-look="underline"] {
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--sg-border-subtle);
  border-radius: 0;
  padding: 0;
  gap: 0.25rem;
  box-shadow: none;
  width: 100%;
}

.sg-tabs-list[data-look="underline"] .sg-tabs-trigger {
  border-radius: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
}

.sg-tabs-list[data-look="underline"] .sg-tabs-trigger[data-active="true"] {
  background: transparent;
  color: var(--sg-accent);
  border-bottom-color: var(--sg-accent);
  box-shadow: none;
}

.sg-tabs-list[data-look="underline"]
  .sg-tabs-trigger[data-active="true"]:hover:not(:disabled) {
  background: transparent;
  color: var(--sg-accent-hover);
}

.sg-tabs-list[data-look="segmented"] {
  width: 100%;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  border-radius: var(--sg-radius-md);
  padding: 0.3rem;
}

.sg-tabs-list[data-look="segmented"] .sg-tabs-trigger {
  justify-content: center;
  width: 100%;
  border-radius: var(--sg-radius-sm);
}

/* ========== AVATAR LOOKS ========== */
.sg-avatar[data-look="rounded"] {
  border-radius: var(--sg-radius-md);
}

.sg-avatar[data-look="soft"] {
  border-radius: var(--sg-radius-lg);
  box-shadow: var(--sg-shadow-soft);
  border-width: 2px;
}

/* ========== TOOLTIP LOOKS ========== */
.sg-tooltip[data-look="solid"] {
  background: var(--sg-fg);
  color: var(--sg-bg);
  border-color: transparent;
}

.sg-tooltip[data-look="solid"] .sg-tooltip-arrow {
  background: var(--sg-fg);
  border-color: transparent;
}

.sg-tooltip[data-look="accent"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
}

.sg-tooltip[data-look="accent"] .sg-tooltip-arrow {
  background: var(--sg-accent);
  border-color: transparent;
}

/* ========== CARD LOOKS ========== */
.sg-card[data-look="flat"] {
  box-shadow: none;
}

.sg-card[data-look="raised"] {
  box-shadow: var(--sg-shadow-elevated);
}

.sg-card[data-look="outline"] {
  box-shadow: none;
  background: transparent;
  border-color: var(--sg-border-frost);
}

.sg-card[data-look="glow"] {
  box-shadow:
    var(--sg-shadow-soft),
    0 0 0 1px color-mix(in srgb, var(--sg-accent) 20%, transparent),
    0 12px 40px color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-card[data-look="glow"]:hover {
  box-shadow:
    var(--sg-shadow-elevated),
    0 0 0 1px color-mix(in srgb, var(--sg-accent) 35%, transparent),
    0 16px 48px color-mix(in srgb, var(--sg-accent) 28%, transparent);
}

/* Modal/Toast enter recipes live in motion-recipes.css via data-motion */

@media (prefers-reduced-motion: reduce) {
  .sg-select-trigger,
  .sg-select-option,
  .sg-shell-nav-item,
  .sg-check-root[data-look="card"],
  .sg-check-root[data-look="chip"] {
    transition: none !important;
    animation: none !important;
  }

  .sg-select-trigger:hover:not(:disabled) {
    transform: none !important;
  }

  .sg-btn-look-neon:hover:not(:disabled),
  .sg-badge-look-glow {
    animation: none !important;
  }
}

/**
 * Motion recipes — driven by data-motion on each control.
 * Defaults are set in React (MOTION_DEFAULTS). Reduced-motion hard-stops below.
 */

/* —— Button —— */
.sg-btn[data-motion="none"] {
  transition: background var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    color var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth) !important;
}

.sg-btn[data-motion="none"]:hover:not(:disabled),
.sg-btn[data-motion="none"]:active:not(:disabled) {
  transform: none !important;
}

.sg-btn[data-motion="lift"]:hover:not(:disabled):not(.sg-btn-loading) {
  transform: translateY(-1px);
}

.sg-btn[data-motion="lift"]:active:not(:disabled):not(.sg-btn-loading) {
  transform: translateY(1px) scale(0.98);
}

.sg-btn[data-motion="press"]:hover:not(:disabled):not(.sg-btn-loading) {
  transform: none;
}

.sg-btn[data-motion="press"]:active:not(:disabled):not(.sg-btn-loading) {
  transform: scale(0.96);
}

.sg-btn[data-motion="sheen"] {
  background-size: 200% 100%;
  overflow: hidden;
  position: relative;
}

.sg-btn[data-motion="sheen"]:hover:not(:disabled):not(.sg-btn-loading) {
  animation: sg-sheen 0.9s var(--sg-ease-smooth);
  transform: translateY(-1px);
}

.sg-btn[data-motion="ripple"] {
  position: relative;
  overflow: hidden;
}

.sg-btn[data-motion="ripple"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at var(--sg-ripple-x, 50%) var(--sg-ripple-y, 50%),
    color-mix(in srgb, #fff 35%, transparent) 0%,
    transparent 55%
  );
  opacity: 0;
  transform: scale(0.2);
  pointer-events: none;
  transition:
    opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    transform var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-btn[data-motion="ripple"]:active:not(:disabled)::after {
  opacity: 1;
  transform: scale(1.6);
  transition: none;
}

/* —— Checkbox / Radio control face —— */
.sg-check-root[data-motion="none"] .sg-check-control,
.sg-check-root[data-motion="none"] {
  animation: none !important;
  transition: background var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth) !important;
}

.sg-check-root[data-motion="none"]:hover .sg-check-control {
  transform: none !important;
}

.sg-check-root[data-motion="pop"] .sg-check-control[data-checked="true"] {
  animation: sg-pop var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-check-root[data-motion="bounce"] .sg-check-control[data-checked="true"] {
  animation: sg-bounce-check var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-check-root[data-motion="fade-in"] .sg-check-mark,
.sg-check-root[data-motion="fade-in"] .sg-check-dot {
  transition: opacity var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-check-root[data-motion="fade-in"] .sg-check-control:not([data-checked="true"]) .sg-check-mark,
.sg-check-root[data-motion="fade-in"] .sg-check-control:not([data-checked="true"]) .sg-check-dot {
  opacity: 0;
}

.sg-check-root[data-motion="draw"] .sg-check-mark path {
  stroke-dasharray: 24;
  stroke-dashoffset: 24;
  transition: stroke-dashoffset var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-check-root[data-motion="draw"]
  .sg-check-control[data-checked="true"]
  .sg-check-mark
  path {
  stroke-dashoffset: 0;
}

.sg-check-root[data-motion="dot-scale"] .sg-check-dot {
  transition: transform var(--sg-motion-med) var(--sg-ease-spring);
  transform: scale(0);
}

.sg-check-root[data-motion="dot-scale"]
  .sg-check-control[data-checked="true"]
  .sg-check-dot {
  transform: scale(1);
}

.sg-check-root[data-motion="ring-expand"] .sg-check-control {
  transition:
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    background var(--sg-motion-med) var(--sg-ease-smooth),
    transform var(--sg-motion-fast) var(--sg-ease-spring);
}

.sg-check-root[data-motion="ring-expand"]
  .sg-check-control[data-checked="true"] {
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

/* —— Switch —— */
.sg-switch[data-motion="none"] .sg-switch-thumb {
  transition: background var(--sg-motion-fast) var(--sg-ease-smooth) !important;
  transition-property: background !important;
}

.sg-switch[data-motion="snap"] .sg-switch-thumb {
  transition: transform 120ms linear, background var(--sg-motion-fast) linear;
}

.sg-switch[data-motion="spring"] .sg-switch-thumb {
  transition: transform var(--sg-motion-med) var(--sg-ease-spring),
    background var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-fast) var(--sg-ease-smooth);
}

.sg-switch[data-motion="elastic"] .sg-switch-thumb {
  transition: transform 320ms cubic-bezier(0.34, 1.7, 0.64, 1),
    background var(--sg-motion-fast) var(--sg-ease-smooth);
}

/* —— Field (input / textarea) —— */
.sg-input[data-motion="none"]:focus,
.sg-textarea[data-motion="none"]:focus {
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
  transition: none;
}

.sg-input[data-motion="ring"],
.sg-textarea[data-motion="ring"] {
  transition:
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    background var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-input[data-motion="glow"]:focus,
.sg-textarea[data-motion="glow"]:focus {
  box-shadow:
    0 0 0 3px var(--sg-ring-soft),
    0 0 18px color-mix(in srgb, var(--sg-accent) 28%, transparent);
}

.sg-input[data-motion="underline-grow"],
.sg-textarea[data-motion="underline-grow"] {
  background-image: linear-gradient(var(--sg-accent), var(--sg-accent));
  background-size: 0% 2px;
  background-position: left bottom;
  background-repeat: no-repeat;
  transition:
    background-size var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-fast) var(--sg-ease-smooth);
}

.sg-input[data-motion="underline-grow"]:focus,
.sg-textarea[data-motion="underline-grow"]:focus {
  background-size: 100% 2px;
}

/* —— Select / Popover / DropdownMenu / DatePicker panel open —— */
.sg-select-menu[data-motion="none"],
.sg-popover-content[data-motion="none"],
.sg-menu-content[data-motion="none"],
.sg-datepicker-panel[data-motion="none"] {
  animation: none !important;
}

.sg-select-menu[data-motion="fade"],
.sg-popover-content[data-motion="fade"],
.sg-menu-content[data-motion="fade"],
.sg-datepicker-panel[data-motion="fade"] {
  animation: sg-fade-in var(--sg-motion-fast) var(--sg-ease-smooth);
}

.sg-select-menu[data-motion="scale"],
.sg-popover-content[data-motion="scale"],
.sg-menu-content[data-motion="scale"],
.sg-datepicker-panel[data-motion="scale"] {
  animation: sg-scale-in var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-select-menu[data-motion="slide-down"],
.sg-popover-content[data-motion="slide-down"],
.sg-menu-content[data-motion="slide-down"],
.sg-datepicker-panel[data-motion="slide-down"] {
  animation: sg-slide-down-in var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-select-trigger[data-motion="scale"] .sg-select-chevron,
.sg-select-trigger[data-open="true"] .sg-select-chevron {
  transition: transform var(--sg-motion-fast) var(--sg-ease-spring);
}

/* —— Tooltip —— */
.sg-tooltip[data-motion="none"] {
  transition: opacity var(--sg-motion-fast) linear, visibility 0s linear !important;
  transform: translateX(-50%) translateY(0) scale(1) !important;
}

.sg-tooltip[data-motion="fade"] {
  transition: opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    visibility var(--sg-motion-fast) var(--sg-ease-smooth);
  transform: translateX(-50%) translateY(0) !important;
}

.sg-tooltip[data-motion="scale"] {
  transition:
    opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    visibility var(--sg-motion-fast) var(--sg-ease-smooth),
    transform var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-tooltip[data-motion="slide"][data-placement="top"],
.sg-tooltip[data-motion="slide"]:not([data-placement]) {
  transform: translateX(-50%) translateY(6px) scale(1);
}

.sg-tooltip[data-motion="slide"][data-placement="top"][data-open="true"],
.sg-tooltip[data-motion="slide"]:not([data-placement])[data-open="true"] {
  transform: translateX(-50%) translateY(0) scale(1);
}

.sg-tooltip[data-motion="slide"][data-placement="bottom"] {
  transform: translateX(-50%) translateY(-6px) scale(1);
}

.sg-tooltip[data-motion="slide"][data-placement="bottom"][data-open="true"] {
  transform: translateX(-50%) translateY(0) scale(1);
}

/* —— Badge —— */
.sg-badge[data-motion="none"] {
  animation: none !important;
}

.sg-badge[data-motion="pulse"] {
  animation: sg-pulse-soft 2.4s ease-in-out infinite;
}

.sg-badge[data-motion="pop-in"] {
  animation: sg-pop var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-badge[data-motion="shimmer"] {
  background-size: 200% 100%;
  animation: sg-sheen 2.2s linear infinite;
}

/* —— Avatar —— */
.sg-avatar[data-motion="none"]:hover {
  transform: none !important;
}

.sg-avatar[data-motion="lift"]:hover {
  transform: scale(1.05);
}

.sg-avatar[data-motion="ring-pulse"] {
  animation: sg-pulse-soft 2.2s ease-in-out infinite;
}

.sg-avatar[data-motion="status-ping"] {
  position: relative;
}

.sg-avatar[data-motion="status-ping"]::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 999px;
  background: var(--sg-success);
  border: 2px solid var(--sg-bg);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--sg-success) 45%, transparent);
  animation: sg-status-ping 1.8s ease-out infinite;
}

/* —— Tabs —— */
.sg-tabs-list {
  position: relative;
}

.sg-tabs-indicator {
  position: absolute;
  z-index: 0;
  top: 0;
  left: 0;
  pointer-events: none;
  border-radius: inherit;
  background: var(--sg-accent);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  width: var(--sg-tabs-iw, 0px);
  height: var(--sg-tabs-ih, 0px);
  transform: translate3d(var(--sg-tabs-ix, 0px), var(--sg-tabs-iy, 0px), 0);
  transition:
    transform var(--sg-motion-med) var(--sg-ease-spring),
    width var(--sg-motion-med) var(--sg-ease-spring),
    height var(--sg-motion-med) var(--sg-ease-smooth),
    opacity var(--sg-motion-fast) var(--sg-ease-smooth);
  will-change: transform, width;
}

.sg-tabs-list[data-motion="none"] .sg-tabs-indicator,
.sg-tabs-list[data-motion="fade"] .sg-tabs-indicator {
  display: none;
}

.sg-tabs-list[data-motion="slide"] .sg-tabs-trigger {
  position: relative;
  z-index: 1;
  background: transparent;
}

.sg-tabs-list[data-motion="slide"] .sg-tabs-trigger[data-active="true"] {
  background: transparent;
  color: var(--sg-accent-fg);
  box-shadow: none;
}

.sg-tabs-list[data-motion="slide"]
  .sg-tabs-trigger[data-active="true"]:hover:not(:disabled) {
  background: transparent;
  color: var(--sg-accent-fg);
}

/* Underline look: indicator is a bottom bar (X only) */
.sg-tabs-list[data-look="underline"][data-motion="slide"] .sg-tabs-indicator {
  height: 2px !important;
  top: auto;
  bottom: 0;
  border-radius: 999px;
  box-shadow: none;
  background: var(--sg-accent);
  transform: translate3d(var(--sg-tabs-ix, 0px), 0, 0);
}

.sg-tabs-list[data-look="underline"][data-motion="slide"]
  .sg-tabs-trigger[data-active="true"] {
  color: var(--sg-accent);
  border-bottom-color: transparent;
}

.sg-tabs-list[data-look="underline"][data-motion="slide"]
  .sg-tabs-trigger[data-active="true"]:hover:not(:disabled) {
  color: var(--sg-accent-hover);
}

.sg-tabs-list[data-look="segmented"][data-motion="slide"] .sg-tabs-indicator {
  border-radius: var(--sg-radius-sm);
}

.sg-tabs-list[data-motion="fade"] .sg-tabs-trigger {
  transition:
    background var(--sg-motion-med) var(--sg-ease-smooth),
    color var(--sg-motion-med) var(--sg-ease-smooth),
    border-color var(--sg-motion-fast) var(--sg-ease-smooth),
    box-shadow var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-tabs-list[data-motion="none"] .sg-tabs-trigger {
  transition: none !important;
}

.sg-tabs-content[data-motion="fade"],
.sg-tabs-content[data-motion="slide"] {
  animation: sg-fade-in var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-tabs-content[data-motion="none"] {
  animation: none !important;
}

/* —— Modal —— */
.sg-modal-root[data-motion="none"] .sg-modal-panel,
.sg-modal-root[data-motion="none"] .sg-modal-backdrop {
  animation: none !important;
}

.sg-modal-root[data-motion="scale"] .sg-modal-panel {
  animation: sg-scale-in var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-modal-root[data-motion="fade"] .sg-modal-panel {
  animation: sg-fade-in var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-modal-root[data-motion="slide-up"] .sg-modal-panel {
  animation: sg-slide-up-in var(--sg-motion-med) var(--sg-ease-spring);
}

/* Modal exit (presence holds mount ~200ms) */
.sg-modal-root[data-state="closed"] .sg-modal-backdrop {
  animation: sg-fade-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-modal-root[data-state="closed"][data-motion="scale"] .sg-modal-panel {
  animation: sg-scale-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-modal-root[data-state="closed"][data-motion="fade"] .sg-modal-panel {
  animation: sg-fade-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-modal-root[data-state="closed"][data-motion="slide-up"] .sg-modal-panel {
  animation: sg-slide-up-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-modal-root[data-state="closed"][data-motion="none"] .sg-modal-panel,
.sg-modal-root[data-state="closed"][data-motion="none"] .sg-modal-backdrop {
  animation: none !important;
}

/* Overlay menus / popover / datepicker exit */
.sg-select-menu[data-state="closed"],
.sg-popover-content[data-state="closed"],
.sg-menu-content[data-state="closed"],
.sg-datepicker-panel[data-state="closed"] {
  pointer-events: none;
}

.sg-select-menu[data-state="closed"][data-motion="scale"],
.sg-popover-content[data-state="closed"][data-motion="scale"],
.sg-menu-content[data-state="closed"][data-motion="scale"],
.sg-datepicker-panel[data-state="closed"][data-motion="scale"],
.sg-select-menu[data-state="closed"]:not([data-motion]),
.sg-popover-content[data-state="closed"]:not([data-motion]),
.sg-menu-content[data-state="closed"]:not([data-motion]),
.sg-datepicker-panel[data-state="closed"]:not([data-motion]) {
  animation: sg-overlay-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-select-menu[data-state="closed"][data-motion="fade"],
.sg-popover-content[data-state="closed"][data-motion="fade"],
.sg-menu-content[data-state="closed"][data-motion="fade"],
.sg-datepicker-panel[data-state="closed"][data-motion="fade"] {
  animation: sg-fade-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-select-menu[data-state="closed"][data-motion="slide-down"],
.sg-popover-content[data-state="closed"][data-motion="slide-down"],
.sg-menu-content[data-state="closed"][data-motion="slide-down"],
.sg-datepicker-panel[data-state="closed"][data-motion="slide-down"] {
  animation: sg-slide-down-out var(--sg-duration-normal) var(--sg-ease-out)
    forwards;
}

.sg-select-menu[data-state="closed"][data-motion="none"],
.sg-popover-content[data-state="closed"][data-motion="none"],
.sg-menu-content[data-state="closed"][data-motion="none"],
.sg-datepicker-panel[data-state="closed"][data-motion="none"] {
  animation: none !important;
}

/* —— Toast —— */
.sg-toast[data-motion="none"] {
  animation: none !important;
}

.sg-toast[data-motion="slide-in"] {
  animation: sg-toast-in var(--sg-motion-med) var(--sg-ease-spring);
}

.sg-toast[data-motion="pop"] {
  animation: sg-pop var(--sg-motion-med) var(--sg-ease-spring);
}

/* Stack reflow — siblings ease when a toast leaves */
.sg-toast-viewport {
  transition: gap var(--sg-motion-fast) var(--sg-ease-smooth);
}

.sg-toast {
  transition:
    transform var(--sg-motion-med) var(--sg-ease-spring),
    opacity var(--sg-motion-fast) var(--sg-ease-smooth),
    margin var(--sg-motion-med) var(--sg-ease-smooth);
}

.sg-toast[data-leaving="true"] {
  pointer-events: none;
}

.sg-toast[data-leaving="true"][data-motion="slide-in"],
.sg-toast[data-leaving="true"]:not([data-motion]) {
  animation: sg-toast-out var(--sg-duration-normal) var(--sg-ease-out) forwards;
}

.sg-toast[data-leaving="true"][data-motion="pop"] {
  animation: sg-toast-pop-out var(--sg-duration-normal) var(--sg-ease-out)
    forwards;
}

.sg-toast[data-leaving="true"][data-motion="none"] {
  animation: none !important;
  opacity: 0;
}

/* —— Card —— */
.sg-card[data-motion="none"].sg-card-hoverable:hover {
  transform: none !important;
}

.sg-card[data-motion="lift"].sg-card-hoverable:hover {
  transform: translateY(-2px);
}

.sg-card[data-motion="glow-pulse"] {
  animation: sg-pulse-soft 2.8s ease-in-out infinite;
}

/* —— Shared keyframes (motion pack) —— */
@keyframes sg-bounce-check {
  0% {
    transform: scale(0.7);
  }
  50% {
    transform: scale(1.14);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes sg-slide-down-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sg-slide-up-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes sg-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes sg-scale-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.97);
  }
}

@keyframes sg-slide-up-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
}

@keyframes sg-slide-down-out {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(-6px);
  }
}

@keyframes sg-overlay-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
}

@keyframes sg-toast-pop-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.92);
  }
}

@keyframes sg-status-ping {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--sg-success) 45%, transparent);
  }
  70% {
    box-shadow: 0 0 0 8px color-mix(in srgb, var(--sg-success) 0%, transparent);
  }
  100% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--sg-success) 0%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sg-btn,
  .sg-check-control,
  .sg-check-root,
  .sg-switch,
  .sg-switch-thumb,
  .sg-input,
  .sg-textarea,
  .sg-select-menu,
  .sg-popover-content,
  .sg-menu-content,
  .sg-datepicker-panel,
  .sg-select-menu[data-state="closed"],
  .sg-popover-content[data-state="closed"],
  .sg-menu-content[data-state="closed"],
  .sg-datepicker-panel[data-state="closed"],
  .sg-tooltip,
  .sg-badge,
  .sg-avatar,
  .sg-tabs-indicator,
  .sg-tabs-trigger,
  .sg-tabs-content,
  .sg-modal-panel,
  .sg-modal-backdrop,
  .sg-toast,
  .sg-card {
    animation: none !important;
    transition: none !important;
  }

  .sg-btn:hover,
  .sg-btn:active,
  .sg-avatar:hover,
  .sg-card-hoverable:hover,
  .sg-check-root:hover .sg-check-control {
    transform: none !important;
  }

  .sg-tabs-indicator {
    transition: none !important;
  }

  .sg-avatar[data-motion="status-ping"]::after {
    animation: none !important;
  }
}

